contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Attempt to show that only the owner can make sendTo succeed.
    // Parameters:
    // - caller: the address from which we simulate the call by transferring control via this contract;
    // - receiver: the address to receive funds in c.sendTo;
    // - amount: the value to send from this test contract to C before invoking sendTo (so C has balance).

    // NOTE: This contract cannot change msg.sender when calling c.sendTo; tests assume the verifier will check
    // the behavior when this contract (not owner) calls. The distinguishing rule is expressed via the revert
    // outcome of calling sendTo from this contract: on the original P, sendTo reverts unless caller==owner,
    // so calling from a non-owner will revert; on the mutant M which requires receiver==owner, the call may
    // succeed even when this contract is not owner if receiver==owner. We encode this by asserting that when
    // this contract is not the owner, calling sendTo to a receiver that is not this contract's address must revert.

    // The single public test function performs a single state-changing call on c and finishes with one assert.
    function runTest(address receiver, uint256 amount) public payable {
        // Precondition: this contract must hold enough Ether to fund C for the transfer
        require(address(this).balance >= amount, "insufficient balance for funding C");

        // Fund C so c can transfer out 'amount'
        (bool ok,) = address(c).call{value: amount}("");
        require(ok, "funding C failed");

        // We now call c.sendTo from THIS contract (msg.sender == this contract). On the original program P,
        // sendTo requires msg.sender == owner, so since this contract is not necessarily owner, the call should revert
        // unless this contract is the owner. To make the rule general and parameterized, we assert that if the
        // receiver is not this contract, then this contract cannot successfully make c send funds (i.e., call reverts).

        // Make the call and capture whether it reverts.
        bool success;
        (success,) = address(c).call(abi.encodeWithSignature("sendTo(address,uint256)", receiver, amount));

        // The distinguishing rule: when THIS contract is not the owner (unknown to us), calling sendTo to any
        // receiver different from THIS contract must not succeed. Expressed as: if receiver != address(this) then call failed.
        assert( !(receiver != address(this)) || !success );
    }

    // Allow the contract to receive Ether for funding
    receive() external payable {}
}

